<template>
  <div class="rules-backend page-container"><header class="page-heading"><div><span class="eyebrow">ANNOTATION QUALITY / GOVERNANCE</span><h1>标注质量管理模块及规则配置后台</h1><p>配置自动校验、一致性判定、质量评分、抽检仲裁和标注员绩效核算规则，不直接执行质检业务。</p></div><el-button @click="router.push('/annotation-quality')">返回质量管理中心</el-button></header><el-tabs v-model="active"><el-tab-pane label="自动校验规则" name="validation"><RuleTable :rules="rules" @edit="edit" @remove="remove" @toggle="toggle" /><el-alert title="支持文本、图片、视频、表格标注合法性校验；启用规则后由质量中心的自动校验动作执行。" type="info" show-icon :closable="false" /></el-tab-pane><el-tab-pane label="一致性与仲裁" name="consistency"><el-card shadow="never"><el-form :model="config" label-position="top"><el-row :gutter="20"><el-col :span="12"><el-form-item label="多人标注相似度阈值"><el-slider v-model="config.similarityThreshold" :min="0" :max="1" :step=".05" show-input /></el-form-item><el-form-item label="分歧自动触发仲裁比例"><el-slider v-model="config.disputeRate" :min="0" :max="1" :step=".05" show-input /></el-form-item></el-col><el-col :span="12"><el-form-item label="最大允许标注轮次"><el-input-number v-model="config.maxRounds" :min="1" :max="20" /></el-form-item><el-form-item label="仲裁操作人员权限"><el-select v-model="config.arbitratorRole" style="width:100%"><el-option label="管理员" value="ADMIN" /><el-option label="管理员 + 质量专员" value="QUALITY" /></el-select></el-form-item></el-col></el-row></el-form></el-card></el-tab-pane><el-tab-pane label="质量评分权重" name="score"><el-card shadow="never"><p class="tip">综合质量分 = 审核通过率 × 权重 + 一致性率 × 权重 + 校验合格率 × 权重 - 纠偏扣分 - 仲裁扣分</p><el-form :model="config" label-position="top"><el-row :gutter="16"><el-col v-for="field in weightFields" :key="field.key" :span="8"><el-form-item :label="field.label"><el-input-number v-model="config[field.key]" :min="0" :max="1" :step=".05" /></el-form-item></el-col></el-row></el-form></el-card></el-tab-pane><el-tab-pane label="抽检与绩效规则" name="sampling"><el-card shadow="never"><el-form :model="config" label-position="top"><el-row :gutter="20"><el-col :span="12"><el-form-item label="批量随机抽检比例"><el-slider v-model="config.sampleRate" :min=".05" :max="1" :step=".05" show-input /></el-form-item><el-form-item label="驳回重标是否扣绩效"><el-switch v-model="config.rejectPenalty" active-text="计入扣分" inactive-text="不扣分" /></el-form-item></el-col><el-col :span="12"><el-form-item label="绩效统计周期"><el-radio-group v-model="config.period"><el-radio label="DAY">日</el-radio><el-radio label="WEEK">周</el-radio><el-radio label="MONTH">月</el-radio></el-radio-group></el-form-item><el-form-item label="有效标注计分标准"><el-input-number v-model="config.validScore" :min="0" :max="100" /></el-form-item><el-form-item label="仲裁失败扣分"><el-input-number v-model="config.arbitrationPenalty" :min="0" :max="100" /></el-form-item></el-col></el-row></el-form></el-card></el-tab-pane></el-tabs><div class="footer-actions"><el-button @click="restore">恢复默认配置</el-button><el-button @click="snapshot">保存版本快照</el-button><el-button type="primary" @click="saveConfig">保存全部配置</el-button></div><el-dialog v-model="dialog" :title="editing.id ? '编辑规则' : '新增规则'" width="520px"><el-form :model="editing" label-position="top"><el-form-item label="规则名称"><el-input v-model="editing.name" /></el-form-item><el-form-item label="规则编码"><el-input v-model="editing.code" :disabled="!!editing.id" /></el-form-item><el-form-item label="规则类型"><el-select v-model="editing.ruleType" style="width:100%"><el-option label="最低置信度" value="MIN_CONFIDENCE" /><el-option label="标签合法性" value="LABEL_IN_SCHEMA" /><el-option label="正则校验" value="REGEX" /></el-select></el-form-item><el-form-item label="阈值"><el-input-number v-model="editing.threshold" :min="0" :max="1" :step=".05" /></el-form-item><el-form-item label="处理动作"><el-select v-model="editing.action" style="width:100%"><el-option label="进入复核" value="REVIEW" /><el-option label="阻止发布" value="BLOCK" /></el-select></el-form-item><el-form-item label="优先级"><el-input-number v-model="editing.priority" :min="1" :max="999" /></el-form-item><el-form-item label="启用"><el-switch v-model="editing.enabled" /></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="saveRule">保存</el-button></template></el-dialog></div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import request from '../utils/request'
const router = useRouter(); const active = ref('validation'); const rules = ref([]); const dialog = ref(false); const editing = ref({}); const defaults = { similarityThreshold:.8, disputeRate:.2, maxRounds:3, arbitratorRole:'QUALITY', sampleRate:.1, rejectPenalty:true, period:'MONTH', validScore:1, arbitrationPenalty:2, approveWeight:.35, consistencyWeight:.3, validationWeight:.25, correctionPenalty:.05, arbitrationPenaltyWeight:.05 }; const config = reactive({ ...defaults, ...(JSON.parse(localStorage.getItem('river-quality-config') || 'null') || {}) }); const weightFields = computed(() => [{key:'approveWeight',label:'审核通过率权重'},{key:'consistencyWeight',label:'一致性率权重'},{key:'validationWeight',label:'校验合格率权重'},{key:'correctionPenalty',label:'纠偏扣分比例'},{key:'arbitrationPenaltyWeight',label:'仲裁扣分比例'}]); const empty = () => ({ name:'',code:'',ruleType:'MIN_CONFIDENCE',threshold:.7,action:'REVIEW',priority:100,enabled:true });
const load = async () => { try { rules.value = await request.get('/v1/annotation-quality-rules') || []; const saved = await request.get('/v1/system-config/annotation-quality'); if (saved?.configJson) Object.assign(config, JSON.parse(saved.configJson)) } catch(e) { ElMessage.error(e.message || '规则加载失败') } }; const edit = rule => { editing.value = rule ? {...rule} : empty(); dialog.value = true }; const saveRule = async () => { if (!editing.value.name || !editing.value.code) return ElMessage.warning('请填写规则名称和编码'); try { await request.post('/v1/annotation-quality-rules', editing.value); dialog.value = false; await load(); ElMessage.success('规则已保存') } catch(e) { ElMessage.error(e.message) } }; const toggle = async rule => { try { await request.post('/v1/annotation-quality-rules', rule); ElMessage.success('规则状态已更新') } catch(e) { rule.enabled = !rule.enabled; ElMessage.error(e.message) } }; const remove = async rule => { try { await ElMessageBox.confirm(`确认删除规则“${rule.name}”？`); await request.delete(`/v1/annotation-quality-rules/${rule.id}`); await load(); ElMessage.success('规则已删除') } catch(e) { if(e !== 'cancel') ElMessage.error(e.message) } }; const saveConfig = async () => { try { await request.put('/v1/system-config/annotation-quality', JSON.stringify(config), { headers: { 'Content-Type': 'application/json' } }); localStorage.setItem('river-quality-config', JSON.stringify(config)); ElMessage.success('质量配置已保存') } catch(e) { ElMessage.error(e.message || '质量配置保存失败') } }; const snapshot = async () => { try { await request.post('/v1/system-config/annotation-quality/snapshots', JSON.stringify(config), { headers: { 'Content-Type': 'application/json' } }); ElMessage.success('已保存规则版本快照') } catch(e) { ElMessage.error(e.message || '快照保存失败') } }; const restore = () => { Object.assign(config, defaults); ElMessage.info('已恢复默认配置，请点击保存全部配置生效') }; onMounted(load)
</script>

<script>
export default { components: { RuleTable: { props: { rules: Array }, emits: ['edit','remove','toggle'], template: `<div><div class="card-heading"><span>自动校验规则</span><el-button type="primary" size="small" @click="$emit('edit')">新增规则</el-button></div><el-table :data="rules" stripe empty-text="暂无规则"><el-table-column prop="name" label="规则名称"/><el-table-column prop="code" label="编码"/><el-table-column prop="ruleType" label="类型"/><el-table-column prop="threshold" label="阈值"/><el-table-column label="启用"><template #default="s"><el-switch v-model="s.row.enabled" @change="$emit('toggle',s.row)"/></template></el-table-column><el-table-column label="操作"><template #default="s"><el-button link type="primary" @click="$emit('edit',s.row)">编辑</el-button><el-button link type="danger" @click="$emit('remove',s.row)">删除</el-button></template></el-table-column></el-table></div>` } } }
</script>

<style scoped>
.page-heading,.footer-actions,.card-heading{display:flex;align-items:center;justify-content:space-between;gap:16px}.page-heading{margin-bottom:18px}.page-heading h1{margin:6px 0;font-size:26px}.page-heading p,.tip{margin:0;color:#86909c;font-size:13px}.eyebrow{color:#165dff;font-size:12px;font-weight:700;letter-spacing:.08em}.footer-actions{justify-content:flex-end;margin-top:18px}.tip{margin-bottom:20px;line-height:1.6}.footer-actions{padding-bottom:20px}@media(max-width:700px){.page-heading{align-items:flex-start;flex-direction:column}}
</style>
